def findWeightedMedian(n, edges, queries):
    from collections import deque

    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))
        adj[v].append((u, w))

    LOG = 17  # depth < n <= 1e5 < 2^17
    up = [[0] * n for _ in range(LOG)]  # root's parent is itself
    depth = [0] * n
    dist = [0] * n  # weighted distance from root 0

    # Iterative BFS from root (avoids recursion limit)
    seen = [False] * n
    seen[0] = True
    dq = deque([0])
    while dq:
        u = dq.popleft()
        for v, w in adj[u]:
            if not seen[v]:
                seen[v] = True
                up[0][v] = u
                depth[v] = depth[u] + 1
                dist[v] = dist[u] + w
                dq.append(v)

    for k in range(1, LOG):
        prev, cur = up[k - 1], up[k]
        for v in range(n):
            cur[v] = prev[prev[v]]

    def lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        diff = depth[u] - depth[v]
        for k in range(LOG):
            if (diff >> k) & 1:
                u = up[k][u]
        if u == v:
            return u
        for k in reversed(range(LOG)):
            if up[k][u] != up[k][v]:
                u = up[k][u]
                v = up[k][v]
        return up[0][u]

    ans = []
    for u, v in queries:
        if u == v:
            ans.append(u)
            continue
        l = lca(u, v)
        total = dist[u] + dist[v] - 2 * dist[l]
        d_up = dist[u] - dist[l]
        if 2 * d_up >= total:
            # median lies on the u -> lca part: first ancestor x of u
            # with 2 * (dist[u] - dist[x]) >= total
            x = u
            for k in reversed(range(LOG)):
                a = up[k][x]
                if 2 * (dist[u] - dist[a]) < total:
                    x = a
            ans.append(up[0][x])
        else:
            # median lies on the lca -> v part: highest ancestor x of v (below lca)
            # with 2 * (dist[v] - dist[x]) <= total
            x = v
            for k in reversed(range(LOG)):
                a = up[k][x]
                if depth[a] >= depth[l] and 2 * (dist[v] - dist[a]) <= total:
                    x = a
            ans.append(x)
    return ans
